from collections import deque

def find_connected_components(grid):
    """Find connected components of non-background cells."""
    bg = grid[0][0]  # Background
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if visited[r][c]:
                continue
            if grid[r][c] == bg:
                continue

            # BFS to find component
            component = [(r, c)]
            visited[r][c] = True
            queue = deque([(r, c)])

            while queue:
                cr, cc = queue.popleft()
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if not visited[nr][nc] and grid[nr][nc] != bg:
                            visited[nr][nc] = True
                            component.append((nr, nc))
                            queue.append((nr, nc))

            components.append(component)

    return components

def apply_transform(grid, bg):
    """Apply transformation: fill components to dominant color."""
    rows, cols = len(grid), len(grid[0])
    result = [[0] * cols for _ in range(rows)]
    visited = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if visited[r][c] or grid[r][c] == bg:
                result[r][c] = bg
                continue

            # Find component
            component = set()
            component.add((r, c))
            visited[r][c] = True
            queue = deque([(r, c)])

            while queue:
                cr, cc = queue.popleft()
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if (nr, nc) not in component and grid[nr][nc] != bg and not visited[nr][nc]:
                            visited[nr][nc] = True
                            component.add((nr, nc))
                            queue.append((nr, nc))

            # Get dominant non-background color
            counts = {}
            for cr, cc in component:
                if grid[cr][cc] != bg:
                    counts[grid[cr][cc]] = counts.get(grid[cr][cc], 0) + 1

            dominant = max(counts.keys(), key=lambda x: counts[x])

            # Fill component with dominant color
            for cr, cc in component:
                result[cr][cc] = dominant

    return result

