# Try iterative cellular automata approach
def cellular_automata(grid, iterations=10):
    bg = 3
    rows, cols = len(grid), len(grid[0])
    current = [row[:] for row in grid]

    for it in range(iterations):
        new_grid = [[0]*cols for _ in range(rows)]
        changed = False

        for r in range(rows):
            for c in range(cols):
                val = current[r][c]
                if val == bg:
                    new_grid[r][c] = bg
                    continue

                neighbors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(current[nr][nc])

                nb_neighbors = [n for n in neighbors if n != bg]
                bg_neighbors = [n for n in neighbors if n == bg]

                # Rule: if more non-bg neighbors, adopt majority of non-bg
                if len(nb_neighbors) > len(bg_neighbors):
                    counts = {}
                    for n in nb_neighbors:
                        counts[n] = counts.get(n, 0) + 1
                    max_c = max(counts.values())
                    tied = [k for k,v in counts.items() if v == max_c]

                    # Tie-break: if current value is in tie, keep it tight
                    if val in tied:
                        new_grid[r][c] = val
                    else:
                        new_grid[r][c] = max(counts.keys(), key=lambda x: counts[x])
                elif len(bg_neighbors) > len(nb_neighbors):
                    new_grid[r][c] = bg
                else:
                    # Equal non-bg and bg count
                    # Check if current value maintains majority ties
                    if val in counts and counts[val] >= len(nb_neighbors)/2:
                        new_grid[r][c] = val
                    else:
                        new_grid[r][c] = max(counts.keys(), key=lambda x: counts[x]) if counts else bg

            # Check if changed
            if current != new_grid:
                changed = True

        if not changed:
            break

        current = new_grid

    return current

