def iterative_simultaneous(grid, iterations=20):
    bg = 3
    rows, cols = len(grid), len(grid[0])
    current = [row[:] for row in grid]

    for it in range(iterations):
        new_grid = [[0]*cols for _ in range(rows)]

        for r in range(rows):
            for c in range(cols):
                val = current[r][c]
                if val == bg:
                    new_grid[r][c] = bg
                    continue

                neighbors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(current[nr][nc])

                nb_neighbors = [n for n in neighbors if n != bg]
                bg_neighbors = [n for n in neighbors if n == bg]

                # Rule 1: If more non-bg than bg, adopt majority
                if len(nb_neighbors) > len(bg_neighbors):
                    counts = {}
                    for n in nb_neighbors:
                        counts[n] = counts.get(n, 0) + 1
                    max_c = max(counts.values())
                    tied = [k for k,v in counts.items() if v == max_c]
                    # Tie-break: prefer current value
                    if val in tied:
                        new_grid[r][c] = val
                    else:
                        new_grid[r][c] = max(counts.keys(), key=lambda x: counts[x])
                # Rule 2: If more bg than non-bg, become bg
                elif len(bg_neighbors) > len(nb_neighbors):
                    new_grid[r][c] = bg
                # Rule 3: Tie
                else:
                    # Equal non-bg and bg
                    # In tie, depend on cell's own value
                    if val in counts:
                        new_grid[r][c] = val
                    else:
                        new_grid[r][c] = max(counts.keys(), key=lambda x: counts[x]) if counts else bg

        current = new_grid

    return current

