def find_component_of_color(grid, target_color, r, c):
    if grid[r][c] != target_color:
        return []
    visited = []
    queue = [(r, c)]
    seen = {(r, c)}
    while queue:
        curr_r, curr_c = queue.pop(0)
        visited.append((curr_r, curr_c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
