def apply_my_rule(grid, output):
    rows, cols = len(grid), len(grid[0])
    bg = 9
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                output[r][c] = bg
                continue

            # Find all non-bg neighbors
            nonbg_neighbors = []
            same_neighbors = 0
            for dr in [-1,0,1]:
                for dc in [-1,0,1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbor_val = grid[nr][nc]
                        if neighbor_val != bg:
                            nonbg_neighbors.append((nr, nc, neighbor_val))
                            if neighbor_val == val:
                                same_neighbors += 1

            if same_neighbors >= 2:
                output[r][c] = val  # Stay same
            elif len(nonbg_neighbors) > 0:
                # Adjacent to at least one non-bg
                # Determine if a dominant different color exists
                if val not in [n[2] for n in nonbg_neighbors]:
                    # All neighbors are different from self
                    color_counts = {}
                    for nr, nc, v in nonbg_neighbors:
                        color_counts[v] = color_counts.get(v, 0) + 1
                    max_count = max(color_counts.values())
                    if max_count >= 2:
                        winner = [k for k, v in color_counts.items() if v == max_count][0]
                        output[r][c] = winner
                    else:
                        # Pick most common diff
                        output[r][c] = color_counts.most_common(1)[0][0]
                else:
                    # Some neighbors same color, some different
                    # This case shouldn't happen if same_neighbors < 2
                    # Actually it happens: exactly 1 same neighbor
                    output[r][c] = 9  # Hmm, should it become bg or the different neighbor?
            else:
                # No non-bg neighbors
                output[r][c] = bg
    return output

